import type { DocumentContent } from "../documents";

const content = {
    html: resolveAssets("<h1 id=\"memory\">Memory</h1><p>TypeScript, like many managed high level languages, does not encode memory &quot;ownership&quot; in its type system: all reference types are implicitly GC-managed on some (local) heap, and all value types are copied by default.\nThat is convenient and often what we want - and it remains the default in TypeScript-oriented Destack (!) -  but sometimes we want to take additional control of memory, whether for better performance, or just to express certain invariants in the code.\nDestack has a broader, more explicit memory model with four dimensions of <em>opt-in</em> control:</p>\n<ul>\n<li><strong>Ownership</strong>: managed <code>T</code>, (explicitly) owned <code>^T</code>, borrowed <code>&amp;T</code>, or raw <code>*T</code>.</li>\n<li><strong>Access</strong>: readonly, mutable, or exclusive.</li>\n<li><strong>Placement</strong>: relative inside stored type definitions, otherwise <code>local</code> by default or explicitly <code>shared</code> across Workers.</li>\n<li><strong>Lifetime</strong>: provenance of a borrow, such as <code>&quot;static&quot;</code> or <code>&quot;frame&quot;</code>.</li>\n</ul>\n<p>Ownership and placement compose freely, e.g. <code>shared ^T</code> and <code>^shared T</code> both mean an owned value in shared space, and <code>shared &amp;T</code> is a borrow of a shared value.\nPlain old <code>T</code> still behaves as the type&#39;s default representation, exactly like we&#39;re used to from TypeScript: value types are direct values, while reference types are managed references that can be aliased and mutated freely in local space.</p>\n<h2 id=\"ownership\">Ownership</h2><p>Ownership determines who keeps a value alive, who is allowed to mutate it, and when and how it is eventually freed.\nThe notion of ownership has many names and forms, but today it is most commonly associated with Rust&#39;s explicit ownership system, and that is also the system most similar to Destack.\nReally, &quot;ownership&quot; just means that each <em>value</em> has an owner and certain rules apply to how we can pass and store values to certain places, depending on which level of mutability and ownership they need.</p>\n<p>The usual explanation of &quot;ownership&quot; sounds more complex than it is, especially to developers used to &quot;managed&quot; languages, and <em>especially</em> because Rust tradition (deliberately) unifies &quot;liveness&quot;, &quot;exclusivity&quot; and &quot;mutability&quot; while only liveness is required for memory safety.\nUnlike Rust, Destack supports <em>both</em> multiple mutable borrows (<code>&amp;T</code>) and exclusive mutable borrows (<code>&amp;exclusive T</code>):</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Form</th>\n<th>Meaning</th>\n<th>Mutable?</th>\n<th>Exclusive?</th>\n</tr>\n</thead><tbody><tr>\n<td><code>T</code></td>\n<td>default value form: direct for value types, managed for reference types</td>\n<td>yes</td>\n<td>depends on the default form</td>\n</tr>\n<tr>\n<td><code>^T</code></td>\n<td>owned value form</td>\n<td>yes</td>\n<td>yes (single owner)</td>\n</tr>\n<tr>\n<td><code>&amp;T</code></td>\n<td>borrowed access</td>\n<td>yes</td>\n<td>no</td>\n</tr>\n<tr>\n<td><code>&amp;readonly T</code></td>\n<td>readonly borrowed access</td>\n<td>no</td>\n<td>no</td>\n</tr>\n<tr>\n<td><code>&amp;exclusive T</code></td>\n<td>exclusive borrowed access</td>\n<td>yes</td>\n<td>yes</td>\n</tr>\n<tr>\n<td><code>*T</code></td>\n<td>raw pointer</td>\n<td>yes (unchecked)</td>\n<td>no (unchecked)</td>\n</tr>\n</tbody></table></div><p>The owner of a value is responsible for keeping it alive, and also for disposing of the owned value when the parent&#39;s own lifetime ends.\nThe parent (owner) could be in static storage for global constants, it could be another owned or even managed value, or it could be a call frame in a method (in which case we get a stack allocation).</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Ownership</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>   <span data-k=\"comment\">// managed: the runtime owns it</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">owned</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// owned: this binding owns it, dropped after last use</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">borrow</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span>                    <span data-k=\"comment\">// mutable borrow of the managed value</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">view</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">user</span><span data-k=\"punct\">;</span>    <span data-k=\"comment\">// readonly may overlap the mutable borrow</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">claim</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"name\">user</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: the earlier loans are still live</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span>                   <span data-k=\"comment\">// OK: raw pointers are inert and unchecked</span></span></span></code></pre></figure><p>Each ownership form also has a corresponding normalized representation in our little <a href=\"#algebra\">&quot;type algebra&quot;</a>, which means we get to do regular TypeScript-style type space logic, conditionals and remapping (including for lifetimes!).</p>\n<h2 id=\"borrowing\">Borrowing</h2><p>To ensure memory safety even in unmanaged land, Destack follows the Rust idea of using ownership rules to ensure that <em>borrowing</em> a reference <code>&amp;T</code> remains valid - that is, <code>T</code> must remain alive (must not be deallocated) while <em>any</em> <code>&amp;T</code> is active.\nMuch more so than in Rust, Destack infers lifetimes for borrowed values even with complex control flow, so most of the time all lifetimes are inferred correctly and we don&#39;t need to think too much.</p>\n<p>Unlike in Rust, in Destack, mutability is decoupled from borrowing: we can have multiple mutable borrows <code>&amp;T</code> and readonly borrows <code>&amp;readonly T</code> of the same <code>T</code> <em>at the same time</em>, as long as there is no concurrent <code>&amp;exclusive T</code> borrow (which mirrors Rust&#39;s <code>&amp;mut T</code>).\nImportantly, this is still memory safe because all operations that may invalidate a borrow require <code>&amp;exclusive T</code> access.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Form</th>\n<th>Access</th>\n</tr>\n</thead><tbody><tr>\n<td><code>&amp;readonly T</code></td>\n<td>may overlap, cannot mutate through the borrow</td>\n</tr>\n<tr>\n<td><code>&amp;T</code></td>\n<td>may overlap, can mutate through the borrow</td>\n</tr>\n<tr>\n<td><code>&amp;exclusive T</code></td>\n<td>cannot overlap another loan of the same place in execution, can mutate through the borrow</td>\n</tr>\n</tbody></table></div><p>For local managed storage, exclusivity applies to execution through loans rather than ownership or reachability: ordinary managed aliases may still exist, but only one continuation executes between suspension points.\nAn exclusive borrow therefore grants exclusive borrowed access for the operation without implying unique ownership, sole reachability, or a <code>noalias</code> optimization guarantee.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Borrowing</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `&amp;user.name` borrows through the managed `User` reference</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `name` is borrowed access into managed storage</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"><span data-k=\"name\">name</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">point</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">19</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">20</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `&amp;readonly point.x` borrows from owned storage without moving `point`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">21</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">readX</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"property\">x</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">22</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">23</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `&amp;point.x` *can* overlap with readonly borrowed access</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">24</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">writeX</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"property\">x</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">25</span><span class=\"markdown-code-text\"><span data-k=\"punct\">*</span><span data-k=\"name\">writeX</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">26</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">27</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `&amp;point.y` mutably borrows a disjoint field</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">28</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">writeY</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"property\">y</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">29</span><span class=\"markdown-code-text\"><span data-k=\"punct\">*</span><span data-k=\"name\">writeY</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">30</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">31</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// the readonly borrow is still valid here</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">32</span><span class=\"markdown-code-text\"><span data-k=\"name\">readX</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">33</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">34</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `&amp;exclusive point.x` is allowed after the overlapping borrows are no longer live</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">35</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">exclusiveX</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"property\">x</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">36</span><span class=\"markdown-code-text\"><span data-k=\"punct\">*</span><span data-k=\"name\">exclusiveX</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">4</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h3 id=\"stability\">Stability</h3><p>Allowing multiple live mutable borrows is memory safe only because every operation that may <em>invalidate</em> another live borrow requires exclusivity (via <code>&amp;exclusive</code>).\nWriting through a non-exclusive borrow is therefore allowed only when the place to be written to is <strong>overwrite-stable</strong>: the old value requires no destruction, the representation has one fixed layout, and every value observable during a concurrent write remains valid.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Stability</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Frame</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">pixels</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Buffer</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// owned interior storage</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">frame</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Frame</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Frame</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">pixels</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">pixels</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">frame</span><span data-k=\"punct\">.</span><span data-k=\"property\">pixels</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// interior borrow into the owned buffer</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">alias</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">frame</span><span data-k=\"punct\">;</span>         <span data-k=\"comment\">// non-exclusive borrows may overlap</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">*</span><span data-k=\"name\">alias</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Frame</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">pixels</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: overwrite drops the old buffer under `pixels`</span></span></span></code></pre></figure><p>It should be noted that as with the rest of borrowing and ownership, <em>regular</em> managed land needs to know about exactly zero of this because managed references alias freely and mutably.\nWrites through one managed reference can at most result in <em>stale</em> reads through another (a &quot;borrow&quot; into an array taken before it grew still reads the old buffer), which is just ordinary TypeScript aliasing, and not a memory safety problem in itself.</p>\n<h3 id=\"rooting\">Rooting</h3><p>Borrows into managed storage stay valid via &quot;rooting&quot;: the compiler retains and pins every managed object needed by the borrowed path until the borrow&#39;s last use.\nThe collector scans the hidden roots like ordinary reference locals, while pinning keeps interior addresses stable if the collector moves other objects.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Rooting</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Profile</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">constructor</span><span data-k=\"punct\">(</span><span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">        <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">    <span data-k=\"property\">profile</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Profile</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">profile</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span>         <span data-k=\"comment\">// roots and pins the old profile</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">profile</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Profile</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;other&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// OK: the old profile remains valid</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"function\">print</span><span data-k=\"punct\">(</span><span data-k=\"punct\">*</span><span data-k=\"name\">name</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>                          <span data-k=\"comment\">// still reads the borrowed profile</span></span></span></code></pre></figure><p>The hidden slot is just a compiler temporary, and borrows of temporaries follow the same extension rules as Rust: a borrow that initializes a binding extends its temporary to the binding&#39;s lifetime, and any other temporary lives to the end of the enclosing statement.</p>\n<h3 id=\"definite-assignment\">Definite Assignment</h3><p>In general, all bindings must be definitely assigned to <em>something</em> before they can be read / used in any way (read, moved, borrowed, returned, or implicitly dropped):</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Definite Assignment</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">enabled</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"name\">value</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: `value` is not assigned on every path</span></span></span></code></pre></figure><p>When &quot;maybe&quot; state is explicitly desired, we can represent it with a nullish union (or any other union or explicit type as needed):</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Definite Assignment</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Buffer</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">undefined</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">enabled</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"name\">value</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">value</span> <span data-k=\"punct\">!=</span> <span data-k=\"literal\">undefined</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"lifetimes\">Lifetimes</h2><p>Lifetimes are how we tie a borrow to its source, and for the most part, they are inferred and we don&#39;t need to think about them too much.\nIn source, lifetimes are modeled as ordinary comptime parameters (<code>&lt;comptime L: Lifetime&gt;</code> on <code>Borrowed&lt;T, L&gt;</code>), with the familiar compact tick form <code>&#39;a</code> for the common cases:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Source</th>\n<th>Lifetime root</th>\n</tr>\n</thead><tbody><tr>\n<td>static storage</td>\n<td><code>&quot;static&quot;</code></td>\n</tr>\n<tr>\n<td>owned frame storage</td>\n<td><code>&quot;frame&quot;</code></td>\n</tr>\n<tr>\n<td>local managed storage</td>\n<td>the current synchronous region, which ends at the next suspension point</td>\n</tr>\n</tbody></table></div><p>Like <code>Access</code>, <code>Space</code>, and <code>Place</code>, <code>Lifetime</code> is a kind of static <em>value</em>, which is why memory form parameters need the <code>comptime</code> modifier.\nFortunately, the tick spelling for lifetimes (e.g. <code>&#39;a</code>) is much nicer and almost always sufficient, as <code>&lt;&#39;a&gt;</code> declares the comptime lifetime parameter <code>&#39;a</code>, <code>&amp;&#39;a T</code> names a borrow&#39;s lifetime, and <code>View&lt;&#39;a&gt;</code> binds it as an ordinary generic argument.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Lifetimes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">read</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">first</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">items</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">T</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">items</span><span data-k=\"punct\">[</span><span data-k=\"literal\">0</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">pick</span><span data-k=\"punct\">&lt;</span>'c<span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span>'c <span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span>'c <span data-k=\"type\">Node</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span>'c <span data-k=\"type\">Node</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">a</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Lifetime elision - whether you need to write a lifetime parameter explicitly or not - follows the same rules as Rust:</p>\n<ul>\n<li><strong>Type declarations</strong>: structs, classes, enums, and type aliases need their lifetime parameters explicitly.</li>\n<li><strong>Function signatures</strong>: including written function types elide freely: elided borrows complete the signature with hidden generic lifetime parameters.\n(We tried inducing lifetimes implicitly, but that turned out ergonomically weird and a nightmare to implement correctly.)</li>\n</ul>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Lifetimes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// stored borrows write their lifetimes</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">WorldView</span><span data-k=\"punct\">&lt;</span>'e<span data-k=\"punct\">,</span> 'a<span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">engine</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span>'e <span data-k=\"type\">Engine</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">assets</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span>'a <span data-k=\"type\">AssetStore</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// signatures elide, completing hidden lifetime parameters</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">inspect</span><span data-k=\"punct\">(</span><span data-k=\"name\">engine</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Engine</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">engine</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Like in Rust, a signature always means exactly what it says, and nothing is inferred into the lifetimes from the function body.\n(We tried that too, and it caused all sorts of inference complexities and weird action at a distance behavior.)\nThe elision rules are straightforward and a little more general than in Rust:</p>\n<ul>\n<li>With a borrowed receiver, the result takes the receiver&#39;s lifetime.</li>\n<li>With other borrowed inputs, the result takes the union of the input lifetimes.</li>\n<li>With no borrowed inputs at all, the result is <code>&quot;static&quot;</code>.</li>\n</ul>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Lifetimes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// elided form</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">choose</span><span data-k=\"punct\">(</span><span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">flag</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">flag</span> <span data-k=\"punct\">?</span> <span data-k=\"name\">a</span> <span data-k=\"punct\">:</span> <span data-k=\"name\">b</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// explicit form</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">choose</span><span data-k=\"punct\">&lt;</span>'a<span data-k=\"punct\">,</span> 'b<span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span>'a <span data-k=\"type\">Node</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span>'b <span data-k=\"type\">Node</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">    <span data-k=\"name\">flag</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> 'a <span data-k=\"punct\">|</span> 'b<span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">flag</span> <span data-k=\"punct\">?</span> <span data-k=\"name\">a</span> <span data-k=\"punct\">:</span> <span data-k=\"name\">b</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"suspension\">Suspension</h2><p>As discussed in <a href=\"/docs/language/expressions/#continuations\">Continuations</a>, values and objects in &quot;managed land&quot; work exactly like in regular TypeScript and can be referenced and mutated freely wherever.\nWhen <em>borrowing</em> across suspension points (like <code>yield</code> or <code>await</code>), we must still prove that the core safety rules are upheld, i.e. that the borrow source remains alive.\nAnd because multiple continuations may be active concurrently (even if not in parallel), a borrow acquired from local managed storage is rooted in the current synchronous region, and that region ends at the next suspension point.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Suspension</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// owned by the frame: the borrow may cross suspension</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">async</span> <span data-k=\"keyword\">function</span> <span data-k=\"function\">readOwned</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">const</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">await</span> <span data-k=\"function\">tick</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">name</span><span data-k=\"punct\">.</span><span data-k=\"property\">clone</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// borrowed parameter: also fine, the caller proves the source is owned or static</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">async</span> <span data-k=\"keyword\">function</span> <span data-k=\"function\">readBorrowed</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">const</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">await</span> <span data-k=\"function\">tick</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">name</span><span data-k=\"punct\">.</span><span data-k=\"property\">clone</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// managed: rejected, another continuation could touch `user` while we are parked</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">async</span> <span data-k=\"keyword\">function</span> <span data-k=\"function\">readManaged</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">const</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">await</span> <span data-k=\"function\">tick</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: the region rooting `name` ends at this suspension</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">19</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">name</span><span data-k=\"punct\">.</span><span data-k=\"property\">clone</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">20</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>It should be noted that this works precisely because suspension points are always lexically explicit (<code>await</code> and <code>yield</code>, including in function signatures).\nSo, in this case, having &quot;colored functions&quot; is a nice ergonomic tradeoff.</p>\n<h2 id=\"drop\">Drop</h2><p>Whenever the lifetime of a value ends and it is deallocated, Destack supports running a <code>Drop</code> finalizer, similar to Rust&#39;s <code>Drop</code>.\nThis happens when the compiler inserts a drop for an owned local after its last use, when an owned field is being destroyed, and when the runtime <em>eventually</em> reclaims an unreachable managed allocation.\nDrop sites are statically known: maybe-present state must be represented as an explicit type like <code>T | undefined</code>, and a place conditionally moved on one branch is an error at the join, so there are no runtime drop flags as such.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Drop</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">run</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">let</span> <span data-k=\"name\">buffer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Buffer</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span><span data-k=\"name\">buffer</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"comment\">// `buffer` is dropped immediately after its last use</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>The same <code>Drop</code> also works for managed references, where it is run before they are freed:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Drop</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Image</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">pixels</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Unique</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">image</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Image</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Image</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// when `image` is collected, the GC runs `Drop` for `pixels`</span></span></span></code></pre></figure><p>Unlike Rust and C++ RAII, Destack models <code>Drop</code> and <code>Dispose</code> / <code>AsyncDispose</code> separately: <code>Drop</code> follows lifetime, while <a href=\"/docs/language/expressions/#using\"><code>using</code></a> is lexical.\nBecause of this split, <code>Drop</code> <em>can</em> run eagerly after last use, which is great for memory pressure, but also means Destack&#39;s <code>Drop</code> is not the right fit for lexical RAII-style cleanup.\nIn general, <code>Drop</code> should manage memory and memory-shaped cleanup, while <code>using</code> should manage richer resource finalization:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Protocol</th>\n<th>Purpose</th>\n<th>Timing</th>\n</tr>\n</thead><tbody><tr>\n<td><code>Drop</code></td>\n<td>ownership finalization for memory and owned fields</td>\n<td>deterministic for owned values, GC-timed for managed values</td>\n</tr>\n<tr>\n<td><code>Dispose</code></td>\n<td>explicit synchronous resource cleanup</td>\n<td>lexical <code>using</code> scope exit</td>\n</tr>\n<tr>\n<td><code>AsyncDispose</code></td>\n<td>explicit asynchronous resource cleanup</td>\n<td>lexical <code>await using</code> scope exit</td>\n</tr>\n</tbody></table></div><p>External resources such as files, locks, sockets, transactions, and temporary runtime registrations should use <code>Dispose</code> or <code>AsyncDispose</code>, not <code>Drop</code>.\nThis keeps RAII-style cleanup explicit and predictable even though ordinary TS++ values are &quot;managed&quot; by default:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Drop</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">using</span> <span data-k=\"name\">file</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">File</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"name\">path</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">await</span> <span data-k=\"keyword\">using</span> <span data-k=\"name\">connection</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">await</span> <span data-k=\"name\">pool</span><span data-k=\"punct\">.</span><span data-k=\"property\">connect</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Low-level code can of course still control finalization explicitly:\n<code>drop(value)</code> ends ownership immediately, <code>forget(value)</code> intentionally suppresses automatic drop, <code>ManuallyDrop&lt;T&gt;</code> stores a value outside automatic drop handling, and <code>Box&lt;T&gt;.leak()</code> turns one owned allocation into a static borrow.</p>\n<h2 id=\"allocation\">Allocation</h2><p>The primary way to construct new values is <code>new</code>, which initializes a <code>T</code> and produces the ownership form required by the <em>destination</em> type - <code>new</code> is really just an initializer that calls the type&#39;s constructor.\nThe required destination type decides whether that is managed storage, owned storage, inline frame storage, shared storage, or some lower-level allocation form.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Allocation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>   <span data-k=\"comment\">// managed</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// owned</span></span></span></code></pre></figure><p>In some situations it is useful to handle allocation errors directly, and for that Destack supports fallible allocation accessors both via higher level <code>try*</code> methods in standard library types (like <code>Array.tryReserve</code>) and the low level intrinsics (<code>MaybeUninit&lt;T&gt;</code>, <code>Unique&lt;T&gt;</code>, etc.) that they are built on.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Allocation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">try</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">let</span> <span data-k=\"name\">buffer</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Block</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Array</span><span data-k=\"punct\">.</span><span data-k=\"property\">tryWithCapacity</span><span data-k=\"punct\">(</span><span data-k=\"name\">count</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// fallible library allocation</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">let</span> <span data-k=\"name\">page</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Page</span><span data-k=\"punct\">(</span><span data-k=\"name\">buffer</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"name\">page</span><span data-k=\"punct\">.</span><span data-k=\"property\">fill</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">page</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span> <span data-k=\"keyword\">catch</span> <span data-k=\"punct\">(</span><span data-k=\"name\">e</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AllocationError</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"literal\">null</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Code can also opt out of managed allocation locally via <a href=\"/docs/language/expressions/#restrictions\">restrictions</a>:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Allocation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"punct\">@</span><span data-k=\"name\">noManaged</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">processFrame</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"punct\">[</span><span data-k=\"type\">Sample</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Frame</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"function\">buildFrame</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"punct\">@</span><span data-k=\"name\">noHeap</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">interruptHandler</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"punct\">[</span><span data-k=\"type\">Sample</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Frame</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"function\">buildFrameOnStack</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"space\">Space</h2><p>The space of a value determines where it is actually located in memory, and since Destack follows web and TypeScript conventions, the <code>Worker</code>-<em>local</em> heap is the default main memory space.\nOrdinary managed objects, arrays, strings, functions, closures, and module bindings live in local space, and user and library code can almost always just pretend spaces don&#39;t even exist.\nThe actual placement of a type is determined relative to the parent until we find an explicit qualifier or reach the module (which is local by default):</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Space</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">header</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Header</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">body</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">localRequest</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Body</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>                 <span data-k=\"comment\">// relative Body resolves to local</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">sharedRequest</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">shared</span> <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Body</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>         <span data-k=\"comment\">// relative Body resolves to shared</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">mixedRequest</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">local</span> <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">shared</span> <span data-k=\"type\">Body</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>    <span data-k=\"comment\">// explicit Body remains shared</span></span></span></code></pre></figure><p>A value&#39;s &quot;place&quot; is where its bytes are actually stored, <em>not</em> the binding that points to it (copying a managed reference preserves the place of its referent).\nValues never move between spaces, so a <code>shared</code> value cannot be passed where a <code>local</code> value is expected, and vice versa.\nLocal Workers cannot see into other Workers, so a value also cannot move from one Worker&#39;s <code>local</code> space into another&#39;s.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Space</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">replace</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"function\">consumeExclusive</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// OK: `User` means `local User` here</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">sharedUser</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"function\">replace</span><span data-k=\"punct\">(</span><span data-k=\"name\">sharedUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: the parameter is local</span></span></span></code></pre></figure><p>Instance members instead interpret relative types in the receiver&#39;s space, and the destination of <code>new</code> selects the constructor receiver&#39;s space contextually as well:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Space</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Box</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">constructor</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">        <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">user</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">localBox</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">local</span> <span data-k=\"type\">Box</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Box</span><span data-k=\"punct\">(</span><span data-k=\"name\">localUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>   <span data-k=\"comment\">// Box.user is a local User here</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">sharedBox</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">shared</span> <span data-k=\"type\">Box</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Box</span><span data-k=\"punct\">(</span><span data-k=\"name\">sharedUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// and a shared User here</span></span></span></code></pre></figure><p>To work with values from more than one space, we can use the ordinary comptime <code>Space</code> parameter:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Space</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"name\">inspectIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">S</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Space</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Placed</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">S</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"function\">inspectIn</span><span data-k=\"punct\">(</span><span data-k=\"name\">localUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// S = &quot;local&quot;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"function\">inspectIn</span><span data-k=\"punct\">(</span><span data-k=\"name\">sharedUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// S = &quot;shared&quot;</span></span></span></code></pre></figure><p>An unconstrained type parameter may include explicit placement, so its body must be valid for every placement admitted by its bounds.\nAn operation that only some placements grant therefore moves into the signature, where each caller supplies it from concrete storage:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Space</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">reset</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span> <span data-k=\"keyword\">extends</span> <span data-k=\"type\">Resettable</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">item</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"name\">item</span><span data-k=\"punct\">.</span><span data-k=\"property\">reset</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: reset() needs &amp;exclusive this, unprovable for every T</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">reset</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span> <span data-k=\"keyword\">extends</span> <span data-k=\"type\">Resettable</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">item</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"type\">T</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"name\">item</span><span data-k=\"punct\">.</span><span data-k=\"property\">reset</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// OK: the caller acquires where placement is concrete</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"function\">reset</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"name\">users</span><span data-k=\"punct\">[</span><span data-k=\"literal\">0</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// local managed at the call site grants exclusivity</span></span></span></code></pre></figure><p>Finally, a declaration may also choose an intrinsic placement for itself, which forces every use into that space:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Space</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">local <span data-k=\"keyword\">class</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">shared <span data-k=\"keyword\">class</span> <span data-k=\"type\">Channel</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">local <span data-k=\"keyword\">newtype</span> <span data-k=\"type\">TaskId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Channel</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">TaskId</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h3 id=\"shared-space\">Shared Space</h3><p>In TypeScript tradition, each &quot;Worker&quot; (in the JS spec generally referred to as &quot;Agent&quot;) has its own isolated local heap that cannot be touched by other workers.\nFor sharing memory across workers, TypeScript has the <code>SharedArrayBuffer</code> concept and plain old message passing with <code>postMessage</code>.\nThat works, but is architecturally limited and makes it complex to implement more sophisticated parallelism patterns.</p>\n<p>Destack supports an explicit, separate, fully featured <em>shared</em> memory space that is visible to all <code>Worker</code>s in the same <code>Runtime</code> via regular references and objects.\nBasically, <code>shared T</code> is the typed, generalized version of the <code>SharedArrayBuffer</code> idea with the full type system and object graphs at our disposal with the simple rule that local may point into shared, but shared must not point into local memory.\nShared placement permits concurrent access but does not itself provide synchronization; code uses atomics, locks, or higher-level protocols where ordering is required.</p>\n<h3 id=\"shared-module-bindings\">Shared Module Bindings</h3><p>Because Destack inherits the JS/TS Worker model for isolation, module-scoped constants are owned by each <em>Worker</em> and are not actually process-global as they would be in most other languages.\nFor genuinely <em>shared</em> process-global state, the binding <em>itself</em> can be declared as <code>shared</code>.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Form</th>\n<th>Binding place</th>\n<th>Value place</th>\n<th>Meaning</th>\n</tr>\n</thead><tbody><tr>\n<td><code>const world = new World()</code></td>\n<td>local</td>\n<td>local</td>\n<td>one local module binding and one local value</td>\n</tr>\n<tr>\n<td><code>const world: shared World = new World()</code></td>\n<td>local</td>\n<td>shared</td>\n<td>one local binding cell holding one shared reference</td>\n</tr>\n<tr>\n<td><code>shared const world: World = new World()</code></td>\n<td>shared</td>\n<td>shared</td>\n<td>one shared binding cell initialized in shared space</td>\n</tr>\n<tr>\n<td><code>shared const world: shared World = new World()</code></td>\n<td>shared</td>\n<td>shared</td>\n<td>same runtime meaning, explicit for both binding and value</td>\n</tr>\n</tbody></table></div><p>Note that marking the binding itself as <code>shared</code> also types the value as <code>shared</code> (as it is illegal to point from shared storage into local storage anyway, this is convenient).\nShared bindings are always <code>const</code>, and <code>const</code> means exactly what it means in TypeScript: the binding is not reassignable, while the value behind it mutates freely through its own API.\nLike every value stored in shared space, a shared binding&#39;s value must satisfy <code>SharedSafe</code>.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Shared Module Bindings</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">shared <span data-k=\"keyword\">const</span> <span data-k=\"name\">world</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Mutex</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">World</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Mutex</span><span data-k=\"punct\">(</span><span data-k=\"keyword\">new</span> <span data-k=\"type\">World</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">view</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">world</span><span data-k=\"punct\">.</span><span data-k=\"property\">lock</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// guard dereferences to &amp;exclusive World</span></span></span></code></pre></figure><p>Because module code runs on every Worker, shared bindings are initialized exactly once by the runtime, before any other Worker can observe them.</p>\n<h2 id=\"conversions\">Conversions</h2><p>Reference conversions follow directly from <a href=\"#memory\">the five memory rules</a>, and borrowing from a live place works whenever the requested loan rules hold:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Source</th>\n<th>Borrow</th>\n<th>Notes</th>\n</tr>\n</thead><tbody><tr>\n<td>local managed <code>T</code></td>\n<td><code>&amp;T</code> / <code>&amp;readonly T</code> / <code>&amp;exclusive T</code></td>\n<td>exclusive needs no overlapping loan; none may cross <a href=\"#suspension\">suspension</a></td>\n</tr>\n<tr>\n<td>owned <code>^T</code></td>\n<td><code>&amp;T</code> / <code>&amp;readonly T</code> / <code>&amp;exclusive T</code></td>\n<td>owned sources may also cross suspension</td>\n</tr>\n<tr>\n<td>shared owned <code>shared ^T</code></td>\n<td><code>shared &amp;T</code> / <code>shared &amp;readonly T</code> / <code>shared &amp;exclusive T</code></td>\n<td>owned storage stays unique even in shared space because it still has one owner</td>\n</tr>\n<tr>\n<td>shared managed <code>shared T</code></td>\n<td><code>shared &amp;T</code> / <code>shared &amp;readonly T</code></td>\n<td>non-exclusive writes remain limited to overwrite-stable places; synchronization remains separate</td>\n</tr>\n<tr>\n<td>shared managed <code>shared T</code></td>\n<td><code>shared &amp;exclusive T</code></td>\n<td>never: independent Workers prevent exclusive execution</td>\n</tr>\n</tbody></table></div><p>When a managed or owned value appears where a borrow is required, the compiler inserts a borrow coercion whose lifetime and placement are inferred from the source and use:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Conversions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">inspect</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">S</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Space</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Placed</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">S</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">modify</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">S</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Space</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Placed</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">S</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">replace</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">S</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Space</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Placed</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">S</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">localUser</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">local</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">sharedUser</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"function\">inspect</span><span data-k=\"punct\">(</span><span data-k=\"name\">localUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// implicit `local User` to `local &amp;readonly User`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"function\">inspect</span><span data-k=\"punct\">(</span><span data-k=\"name\">sharedUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// implicit `shared User` to `shared &amp;readonly User`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"><span data-k=\"function\">modify</span><span data-k=\"punct\">(</span><span data-k=\"name\">localUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>   <span data-k=\"comment\">// implicit `local User` to `local &amp;User`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\"><span data-k=\"function\">modify</span><span data-k=\"punct\">(</span><span data-k=\"name\">sharedUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// implicit `shared User` to `shared &amp;User`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\"><span data-k=\"function\">replace</span><span data-k=\"punct\">(</span><span data-k=\"name\">localUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// implicit `local User` to `local &amp;exclusive User`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">19</span><span class=\"markdown-code-text\"><span data-k=\"function\">replace</span><span data-k=\"punct\">(</span><span data-k=\"name\">sharedUser</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: shared managed storage cannot grant exclusive access</span></span></span></code></pre></figure><p>The explicit <code>S</code> is what lets these declarations accept both local and shared borrows.\nA declaration written only as <code>inspect(value: &amp;readonly User)</code> accepts a local borrow, like any other bare free-function parameter.\nBorrows can &quot;weaken&quot; (downgrade into a more restrictive form) but cannot be upgraded:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>From</th>\n<th>To</th>\n<th>Notes</th>\n</tr>\n</thead><tbody><tr>\n<td><code>&amp;exclusive T</code></td>\n<td><code>&amp;T</code> / <code>&amp;readonly T</code></td>\n<td>temporary reborrow that suspends the exclusive loan</td>\n</tr>\n<tr>\n<td><code>&amp;T</code></td>\n<td><code>&amp;readonly T</code></td>\n<td>readonly reborrow</td>\n</tr>\n<tr>\n<td>managed reference <code>T</code></td>\n<td><code>^T</code></td>\n<td>never: managed ownership cannot become unique ownership</td>\n</tr>\n<tr>\n<td><code>&amp;T</code></td>\n<td><code>T</code> / <code>^T</code></td>\n<td>never: borrowed access does not own the value</td>\n</tr>\n</tbody></table></div><p>Safe code may convert a borrow into a raw pointer, while converting back requires an unsafe context:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Conversions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">borrow</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span>   <span data-k=\"comment\">// default: a checked borrow</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// typed as raw: an inert, unchecked pointer value</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">again</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">pointer</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// ERROR: pointers only reborrow inside @unsafe</span></span></span></code></pre></figure><h2 id=\"unsafe\">Unsafe</h2><p>Safe Destack code can create and carry raw pointers, because there is nothing directly unsafe about just looking at pointers.\nRaw pointers are inert: they do not keep storage alive, do not participate in borrow checking, and do not prove exclusivity.</p>\n<p>Converting a borrow to a raw pointer is still safe because it does not touch the pointed-to memory:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Unsafe</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">borrow</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">borrow</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// OK: this only creates a raw pointer value</span></span></span></code></pre></figure><p>Unsafe begins when code relies on a memory invariant the compiler cannot prove:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Operation</th>\n<th>Example</th>\n<th>Safe?</th>\n<th>Why</th>\n</tr>\n</thead><tbody><tr>\n<td>create or carry raw pointer values</td>\n<td><code>let pointer: *User = &amp;user</code>, <code>pointer == other</code></td>\n<td>yes</td>\n<td>does not touch memory</td>\n</tr>\n<tr>\n<td>reinterpret raw pointer values</td>\n<td><code>pointer as *uint8</code>, <code>0x1000 as *uint8</code></td>\n<td>yes</td>\n<td>makes no validity claim</td>\n</tr>\n<tr>\n<td>wrapping address arithmetic</td>\n<td><code>wrappingOffset(pointer, 4)</code></td>\n<td>yes</td>\n<td>makes no allocation claim</td>\n</tr>\n<tr>\n<td>allocation-relative pointer math</td>\n<td><code>offset(pointer, 4)</code>, <code>offsetFrom(pointer, origin)</code></td>\n<td>no</td>\n<td>claims same live allocation</td>\n</tr>\n<tr>\n<td>access memory through a pointer</td>\n<td><code>asReference(pointer)</code>, <code>read(pointer)</code>, <code>write(pointer, value)</code></td>\n<td>no</td>\n<td>bypasses borrow checking</td>\n</tr>\n<tr>\n<td>build typed views from raw storage</td>\n<td><code>Slice.fromRaw(pointer, length)</code></td>\n<td>no</td>\n<td>claims a valid region of <code>T</code></td>\n</tr>\n<tr>\n<td>raw bytes and layout tricks</td>\n<td><code>copyBytes(dst, src, n)</code>, <code>readVolatile(pointer)</code>, <code>transmute&lt;T, U&gt;(value)</code></td>\n<td>no</td>\n<td>touches or reinterprets unchecked memory</td>\n</tr>\n</tbody></table></div><p>The compiler rejects unsafe operations, like raw pointer dereferencing, outside explicit <a href=\"/docs/language/expressions/#taint\"><code>@unsafe</code> / <code>@safe</code></a> contexts.</p>\n<h2 id=\"algebra\">Algebra</h2><p>Destack&#39;s &quot;memory algebra&quot; is a fancy way of saying that ownership, access, lifetime, and placement are just types that we can use with TypeScript-style algebra and inference.\nWe can inspect a type&#39;s memory form and build a derived form because qualified types like <code>readonly T</code>, <code>^T</code>, <code>&amp;T</code>, <code>*T</code>, <code>local T</code>, and <code>shared T</code> correspond to builtin intrinsic types and rewrite helpers:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">/// Automatically managed T, owned by the runtime.</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Managed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">intrinsic</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"comment\">/// Owned T (`^T`).</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">intrinsic</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"comment\">/// Borrowed T (`&amp;T`).</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">A</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Access</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;mutable&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">intrinsic</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"comment\">/// Raw T (`*T`).</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Raw</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">intrinsic</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"comment\">/// Placed T (`local T` or `shared T`).</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Placed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">P</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Place</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">intrinsic</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Specifically, all memory sigils and keywords are compact syntax for intrinsic forms that normalize through the same algebra:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">class</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span> <span data-k=\"comment\">/* ... */</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"comment\">/* ... */</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">type <span data-k=\"type\">NormalUser</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                        <span data-k=\"comment\">// unqualified, normal default representation</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">type <span data-k=\"type\">NormalPoint</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>                      <span data-k=\"comment\">// unqualified value type, default-owned/direct</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">type <span data-k=\"type\">ReadonlyUser</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>             <span data-k=\"comment\">// WithAccess&lt;User, &quot;readonly&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">type <span data-k=\"type\">OwnedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                        <span data-k=\"comment\">// Owned&lt;User&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">type <span data-k=\"type\">OwnedPoint</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>                      <span data-k=\"comment\">// Owned&lt;Point&gt;, reduced to Point</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">type <span data-k=\"type\">ReadonlyBorrowedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>    <span data-k=\"comment\">// Borrowed&lt;User, L, &quot;readonly&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">type <span data-k=\"type\">BorrowedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                     <span data-k=\"comment\">// Borrowed&lt;User, L, &quot;mutable&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">type <span data-k=\"type\">ExclusiveBorrowedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// Borrowed&lt;User, L, &quot;exclusive&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\">type <span data-k=\"type\">RawUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                          <span data-k=\"comment\">// Raw&lt;User&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\">type <span data-k=\"type\">LocalUser</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">local</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                   <span data-k=\"comment\">// Placed&lt;User, &quot;local&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\">type <span data-k=\"type\">SharedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                 <span data-k=\"comment\">// Placed&lt;User, &quot;shared&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\">type <span data-k=\"type\">LocalOwnedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">local</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>             <span data-k=\"comment\">// Placed&lt;Owned&lt;User&gt;, &quot;local&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\">type <span data-k=\"type\">SharedOwnedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">shared</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>           <span data-k=\"comment\">// Placed&lt;Owned&lt;User&gt;, &quot;shared&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\">type <span data-k=\"type\">OwnedSharedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">^</span><span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>           <span data-k=\"comment\">// Placed&lt;Owned&lt;User&gt;, &quot;shared&quot;&gt;</span></span></span></code></pre></figure><p>It follows that because forms compose, owning a borrow is different from borrowing an owner:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"comment\">// owns a borrow value</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span> <span data-k=\"comment\">// borrows an owned value</span></span></span></code></pre></figure><p>Destack also provides builtin accessors to inspect composed forms, e.g., <code>PayloadOf&lt;T&gt;</code> removes one outer form, while <code>BaseOf&lt;T&gt;</code> removes all transparent memory forms:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"type\">BaseOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">shared</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">PayloadOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;owned&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Point</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;owned&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;managed&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;owned&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;borrowed&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOr</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;managed&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;managed&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"type\">AccessOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;mutable&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"type\">AccessOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;readonly&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"type\">AccessOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;readonly&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"type\">AccessOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;exclusive&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"type\">LifetimeOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Managed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">never</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"type\">LifetimeOr</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Managed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;static&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;static&quot;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Only borrowed forms carry a lifetime in their type.\nThe lifetime of a borrow acquired from managed or owned storage comes from the concrete value place, so querying a managed type alone yields <code>never</code> rather than inventing a frame provenance.</p>\n<p><code>Space</code> represents one concrete storage space while <code>Place</code> means either a concrete <code>Space</code> or <code>&quot;relative&quot;</code>.\nRelative placement is resolved by a containing receiver and is local at a free declaration:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;relative&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">SpaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">never</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">local</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"type\">SpaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">local</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">local</span> <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"type\">SpaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> <span data-k=\"keyword\">local</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;relative&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">local</span> <span data-k=\"punct\">(</span><span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">Team</span><span data-k=\"punct\">)</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"type\">SpaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">local</span> <span data-k=\"punct\">(</span><span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">Team</span><span data-k=\"punct\">)</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Predicates with <code>Is*</code> are convenience wrappers around those same accessors:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"type\">IsOwned</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">true</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">IsBorrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">true</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"type\">IsShared</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">true</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"type\">IsShared</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">false</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"type\">IsSharedIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">true</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Rewriting helpers preserve the rest of the type instead of rebuilding from a stripped base type:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithSpace</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Placed</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithSpace</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">shared</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"keyword\">shared</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithOwnership</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;owned&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithPlace</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">shared</span> <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;relative&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Placed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;relative&quot;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithAccess</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;readonly&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithAccess</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;readonly&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">^</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithAccess</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;exclusive&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Inside a type declaration, <code>this</code> in type or static position also carries the current instantiated form of that type to query against with the <code>*Of</code> and <code>Is*</code> family.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">lock</span><span data-k=\"punct\">:</span> <span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span>this<span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">==</span> <span data-k=\"string\">&quot;shared&quot;</span> <span data-k=\"punct\">?</span> <span data-k=\"type\">Mutex</span> <span data-k=\"punct\">:</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">localBuffer</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">sharedBuffer</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">shared</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"name\">sharedBuffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">lock</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Mutex</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"name\">localBuffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">lock</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">typeof</span> <span data-k=\"name\">localBuffer</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">typeof</span> <span data-k=\"name\">sharedBuffer</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h2 id=\"polymorphism\">Polymorphism</h2><p>Since ownership, access, lifetime, and placement are all exposed as ordinary comptime values, contracts and implementors can be polymorphic and conditional over ownership, space, and access.\nThe caller chooses the level of control through the expression and its type; owned arguments move in by position without a prefix operator:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Polymorphism</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">owned</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>            <span data-k=\"comment\">// managed/default value</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">user</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// readonly borrowed access</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>           <span data-k=\"comment\">// mutable borrowed access</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"name\">user</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// exclusive borrowed access</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"name\">owned</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>           <span data-k=\"comment\">// owned value, moved into the call</span></span></span></code></pre></figure><p>Dispatch resolution uses the actual form during overload resolution, so container interfaces like <code>Iterable&lt;T&gt;</code> can support ordinary TypeScript iteration and borrowed iteration without adding Rust-style method family explosion:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Polymorphism</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> type <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">points</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Array</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Point</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">ownedPoints</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Array</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Point</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// ordinary &quot;managed&quot; iteration</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// readonly borrowed iteration</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\">    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// mutable borrowed iteration</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\">    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">19</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">20</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// exclusive borrowed iteration</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">21</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">22</span><span class=\"markdown-code-text\">    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">exclusive</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">23</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">24</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">25</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// consuming iteration: an owned collection moves into its iterator by position</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">26</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"name\">ownedPoints</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">27</span><span class=\"markdown-code-text\">    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">28</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"capabilities\">Capabilities</h2><p>Destack encodes memory capabilities as trait-like interfaces, usable as ordinary bounds:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Capability</th>\n<th>Meaning</th>\n</tr>\n</thead><tbody><tr>\n<td><code>Copy</code></td>\n<td>Value can be duplicated implicitly without changing ownership responsibilities.</td>\n</tr>\n<tr>\n<td><code>Clone</code></td>\n<td>Code can explicitly create another value, possibly by running code or allocating.</td>\n</tr>\n<tr>\n<td><code>SharedSafe</code></td>\n<td>Values of the type may be stored in <a href=\"#shared-space\">shared space</a>.</td>\n</tr>\n<tr>\n<td><code>OverwriteStable</code></td>\n<td>Place can be <a href=\"#stability\">overwritten</a> through a non-exclusive mutable access.</td>\n</tr>\n<tr>\n<td><code>DynamicSafe</code></td>\n<td>Type can be erased behind a <a href=\"/docs/language/types/#representation\"><code>dynamic</code></a> carrier.</td>\n</tr>\n<tr>\n<td><code>AtomicSafe</code></td>\n<td>Value has a supported atomic storage representation.</td>\n</tr>\n<tr>\n<td><code>Concrete</code></td>\n<td>Type has one complete storage representation.</td>\n</tr>\n<tr>\n<td><code>Zeroable</code></td>\n<td>Type is valid when all bytes are zero.</td>\n</tr>\n<tr>\n<td><code>Unpin</code></td>\n<td>Value may move out of pinned storage.</td>\n</tr>\n<tr>\n<td><code>Default</code></td>\n<td>Type has a conventional <code>default()</code> value.</td>\n</tr>\n</tbody></table></div><p>The compiler derives representation markers such as <code>Copy</code>, <code>SharedSafe</code>, <code>OverwriteStable</code>, and <code>DynamicSafe</code> structurally.\nMember-bearing capabilities such as <code>Clone</code> and <code>Default</code> use ordinary extension implementations.</p>\n<h2 id=\"synchronization\">Synchronization</h2><p>The standard library provides the usual memory and synchronization primitives on top of this unified memory system.\nThe full details are documented in the library, but the basics should be familiar to anyone with a systems-level background.\nThis is also where the <code>@unsafe</code> actually lives: a <code>Mutex&lt;T&gt;</code> mutates through a non-exclusive receiver via <code>UnsafeCell</code> and atomics, and its guard manufactures the <code>&amp;exclusive T</code> that the runtime lock (not the borrow checker) guarantees.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Primitive</th>\n<th>Behavior</th>\n</tr>\n</thead><tbody><tr>\n<td><code>Box&lt;T&gt;</code></td>\n<td>unique heap ownership for <code>Owned&lt;T&gt;</code>, with deterministic drop when <code>T: Drop</code></td>\n</tr>\n<tr>\n<td><code>Rc&lt;T&gt;</code></td>\n<td>local shared ownership of <code>Owned&lt;T&gt;</code>, non-atomic refcount, not transferable across Workers</td>\n</tr>\n<tr>\n<td><code>Arc&lt;T&gt;</code></td>\n<td>shared ownership of <code>Owned&lt;T&gt;</code>, atomic refcount, transferable as <code>shared Arc&lt;T&gt;</code> of <code>SharedSafe</code> <code>T</code></td>\n</tr>\n<tr>\n<td><code>Cell&lt;T&gt;</code></td>\n<td>local interior mutation by value, for small <code>Copy</code>-like state</td>\n</tr>\n<tr>\n<td><code>RefCell&lt;T&gt;</code></td>\n<td>local runtime borrow checking for cases static borrowing cannot express cleanly</td>\n</tr>\n<tr>\n<td><code>Atomic&lt;T&gt;</code></td>\n<td>lock-free scalar storage with explicit ordering and scope</td>\n</tr>\n<tr>\n<td><code>AsyncMutex&lt;T&gt;</code></td>\n<td>local mutual exclusion that suspends the current async task, not the Worker</td>\n</tr>\n<tr>\n<td><code>Mutex&lt;T&gt;</code></td>\n<td>shared mutual exclusion backed by atomics and runtime wait/wake support</td>\n</tr>\n</tbody></table></div><p>Because ownership and placement are part of our type system, and we can query and gate based on contextual type information using regular TypeScript algebra, we have a lot of flexibility and gain some nice ergonomics.\nFor example, we can provide ergonomic context-aware aliases that conform to the way they are used:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Synchronization</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">type <span data-k=\"type\">Ref</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">extends</span> <span data-k=\"string\">&quot;shared&quot;</span> <span data-k=\"punct\">?</span> <span data-k=\"type\">Arc</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">:</span> <span data-k=\"type\">Rc</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">type <span data-k=\"type\">Lock</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">extends</span> <span data-k=\"string\">&quot;shared&quot;</span> <span data-k=\"punct\">?</span> <span data-k=\"type\">Mutex</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">:</span> <span data-k=\"type\">AsyncMutex</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure>", {  }),
} satisfies DocumentContent;

export default content;

/// Replace build-time asset placeholders with bundled URLs.
function resolveAssets(html: string, assets: Record<string, string>) {
    let resolved = html;

    for (const [placeholder, asset] of Object.entries(assets)) {
        resolved = resolved.replaceAll(placeholder, asset);
    }

    return resolved;
}
